<template><AppShell title="欢迎来到困困" back><view class="auth-page"><GameArt variant="auth" type="crown" class="auth-art" /><text class="auth-title">把时间，留给热爱。</text><text class="muted">交易地铁逃生装备与游戏道具</text><view class="segmented section"><button class="ui-button" :class="{selected:!registering}" @click="registering=false">账号登录</button><button class="ui-button" :class="{selected:registering}" @click="registering=true">注册账号</button></view><view class="section"><label class="field-label" for="username">账号</label><input id="username" v-model="form.username" @blur="form.username=$event.detail.value" class="text-input" placeholder="3–32 位字母、数字或下划线" maxlength="32" /><label class="field-label section" for="password">密码</label><input id="password" v-model="form.password" @blur="form.password=$event.detail.value" class="text-input" placeholder="至少 8 位密码" password maxlength="64" @confirm="form.password=$event.detail.value;submit()" /><template v-if="registering"><label class="field-label section" for="nickname">昵称</label><input id="nickname" v-model="form.nickname" @blur="form.nickname=$event.detail.value" class="text-input" placeholder="大家怎么称呼你" maxlength="24" /></template></view><view class="check-row" @click="agreed=!agreed"><text class="check-box" :class="{checked:agreed}">{{agreed?'✓':''}}</text><text>我已阅读并同意</text><text class="link" @click.stop="go('account/index',{type:'rules'})">用户协议与隐私说明</text></view><view v-if="configError" class="section"><text class="field-error">{{configError}}</text><button class="ui-button text-button" :disabled="configLoading" @click="loadLoginConfig">重新加载协议配置</button></view><text v-if="error" class="field-error">{{error}}</text><button class="ui-button btn wide" :disabled="busy||configLoading||!config?.policyVersion" @click="submit">{{configLoading?'正在加载协议…':busy?'请稍候…':registering?'注册并登录':'登录'}}</button><WechatLogin :agreed="agreed" /><view v-if="config?.simulatedPayment" class="demo-box"><text class="muted tiny">本地演示账号，不涉及真实资金</text><view class="row"><button class="ui-button text-button" @click="demo('buyer')">使用测试买家</button><button class="ui-button text-button" @click="demo('worker')">使用测试卖家</button></view></view></view></AppShell></template>
<script setup>
import {reactive,ref} from 'vue';import WechatLogin from '../../components/WechatLogin.vue';import {onLoad} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import GameArt from '../../components/GameArt.vue';import {request,setSession,loadConfig,go} from '../../lib/api'
const registering=ref(false),agreed=ref(false),busy=ref(false),error=ref(''),config=ref(null),configLoading=ref(true),configError=ref(''),form=reactive({username:'',password:'',nickname:''});onLoad(loadLoginConfig)
async function loadLoginConfig(){configLoading.value=true;configError.value='';try{const result=await loadConfig();if(!result?.policyVersion)throw new Error('协议配置不完整，请稍后重试');config.value=result}catch(e){config.value=null;configError.value=e.message||'协议加载失败，请重试'}finally{configLoading.value=false}}
async function submit(){if(busy.value||configLoading.value)return;if(!config.value?.policyVersion){error.value='请先重新加载协议配置';return}error.value='';if(!agreed.value){error.value='请先阅读并同意用户协议';return}if(!form.username||!form.password){error.value='请填写账号和密码';return}busy.value=true;try{setSession(await request('/boost/auth/'+(registering.value?'register':'login'),'POST',{...form,acceptedPolicy:config.value.policyVersion}));if(getCurrentPages().length>1)uni.navigateBack();else uni.reLaunch({url:'/pages/index/index'})}catch(e){error.value=e.message}finally{busy.value=false}}
function demo(role){form.username='demo_'+role;form.password='Demo2026!';agreed.value=true;registering.value=false;submit()}
</script>
<style scoped>.auth-page{padding:28px 26px;background:#fff;min-height:calc(100vh - 62px)}.auth-art{width:90px;height:90px;border-radius:25px;margin-bottom:20px}.auth-title{display:block;font-size:27px;font-weight:800;margin-bottom:5px}.auth-page .text-input{height:49px}.demo-box{margin-top:30px;padding-top:20px;border-top:1px solid #eee;text-align:center}.demo-box .row{justify-content:center}</style>
